 * FPS Monitor
 * Uses requestAnimationFrame to calculate frames per second
 * Provides start/stop/getFPS API
 */

class FPSMonitor {
  constructor(options = {}) {
    this.threshold = options.threshold || 30; // Default threshold: 30 FPS
    this.warningCallback = options.warningCallback || this.defaultWarningCallback;
    this.isRunning = false;
    this.frameCount = 0;
    this.lastTime = 0;
    this.fps = 0;
    this.animationFrameId = null;
    this.boundLoop = this.loop.bind(this);
  }

  defaultWarningCallback(fps) {
    console.warn(`Low FPS detected: ${fps.toFixed(1)} FPS (threshold: ${this.threshold})`);
  }

  loop(timestamp) {
    if (!this.isRunning) return;

    if (this.lastTime) {
      const delta = timestamp - this.lastTime;
      if (delta >= 1000) {
        this.fps = (this.frameCount * 1000) / delta;
        this.frameCount = 0;
        this.lastTime = timestamp;

        if (this.fps < this.threshold) {
          this.warningCallback(this.fps);
        }
      }
    } else {
      this.lastTime = timestamp;
    }

    this.frameCount++;
    this.animationFrameId = requestAnimationFrame(this.boundLoop);
  }

  start() {
    if (this.isRunning) return;
    this.isRunning = true;
    this.frameCount = 0;
    this.lastTime = 0;
    this.fps = 0;
    this.animationFrameId = requestAnimationFrame(this.boundLoop);
    console.log('FPS Monitor started');
  }

  stop() {
    if (!this.isRunning) return;
    this.isRunning = false;
    if (this.animationFrameId) {
      cancelAnimationFrame(this.animationFrameId);
      this.animationFrameId = null;
    }
    console.log('FPS Monitor stopped');
  }

  getFPS() {
    return this.fps;
  }

  isMonitoring() {
    return this.isRunning;
  }
}

// Singleton instance
let instance = null;

export function createFPSMonitor(options) {
  if (!instance) {
    instance = new FPSMonitor(options);
  }
  return instance;
}

export function getFPSMonitor() {
  return instance;
}

export default FPSMonitor;"}

{"content": "/**
 * Memory Monitor
 * Uses performance.memory API (Chrome) to monitor JS Heap usage
 * Provides getMemoryInfo API
 */

class MemoryMonitor {
  constructor(options = {}) {
    this.warningThreshold = options.warningThreshold || 50 * 1024 * 1024; // 50MB default
    this.criticalThreshold = options.criticalThreshold || 100 * 1024 * 1024; // 100MB default
    this.warningCallback = options.warningCallback || this.defaultWarningCallback;
    this.criticalCallback = options.criticalCallback || this.defaultCriticalCallback;
    this.isSupported = this.checkSupport();
    this.lastCheck = 0;
    this.checkInterval = options.checkInterval || 5000; // Check every 5 seconds
  }

  checkSupport() {
    return typeof performance !== 'undefined' && performance.memory !== undefined;
  }

  defaultWarningCallback(memoryInfo) {
    const usedMB = (memoryInfo.usedJSHeapSize / (1024 * 1024)).toFixed(2);
    const totalMB = (memoryInfo.totalJSHeapSize / (1024 * 1024)).toFixed(2);
    console.warn(`Memory warning: ${usedMB}MB used of ${totalMB}MB total`);
  }

  defaultCriticalCallback(memoryInfo) {
    const usedMB = (memoryInfo.usedJSHeapSize / (1024 * 1024)).toFixed(2);
    const totalMB = (memoryInfo.totalJSHeapSize / (1024 * 1024)).toFixed(2);
    console.error(`Critical memory usage: ${usedMB}MB used of ${totalMB}MB total`);
  }

  getMemoryInfo() {
    if (!this.isSupported) {
      return {
        usedJSHeapSize: 0,
        totalJSHeapSize: 0,
        jsHeapSizeLimit: 0,
        isSupported: false,
        timestamp: Date.now()
      };
    }

    const memory = performance.memory;
    const memoryInfo = {
      usedJSHeapSize: memory.usedJSHeapSize,
      totalJSHeapSize: memory.totalJSHeapSize,
      jsHeapSizeLimit: memory.jsHeapSizeLimit,
      isSupported: true,
      timestamp: Date.now()
    };

    // Check thresholds
    if (memory.usedJSHeapSize > this.criticalThreshold) {
      this.criticalCallback(memoryInfo);
    } else if (memory.usedJSHeapSize > this.warningThreshold) {
      this.warningCallback(memoryInfo);
    }

    return memoryInfo;
  }

  getMemoryUsagePercent() {
    if (!this.isSupported) return 0;
    const memory = performance.memory;
    return (memory.usedJSHeapSize / memory.totalJSHeapSize) * 100;
  }

  getFormattedMemoryInfo() {
    const info = this.getMemoryInfo();
    if (!info.isSupported) {
      return { message: 'Memory monitoring not supported in this browser' };
    }

    return {
      used: `${(info.usedJSHeapSize / (1024 * 1024)).toFixed(2)} MB`,
      total: `${(info.totalJSHeapSize / (1024 * 1024)).toFixed(2)} MB`,
      limit: `${(info.jsHeapSizeLimit / (1024 * 1024)).toFixed(2)} MB`,
      usagePercent: `${this.getMemoryUsagePercent().toFixed(2)}%`,
      timestamp: new Date(info.timestamp).toISOString()
    };
  }

  startPeriodicCheck() {
    if (!this.isSupported) return;

    this.intervalId = setInterval(() => {
      this.getMemoryInfo();
    }, this.checkInterval);
  }

  stopPeriodicCheck() {
    if (this.intervalId) {
      clearInterval(this.intervalId);
      this.intervalId = null;
    }
  }
}

// Singleton instance
let instance = null;

export function createMemoryMonitor(options) {
  if (!instance) {
    instance = new MemoryMonitor(options);
  }
  return instance;
}

export function getMemoryMonitor() {
  return instance;
}

export default MemoryMonitor;", "path": "/Users/charles/Desktop/folder/matrimonial/apps/web-admin/lib/performance/memoryMonitor.js"}

{"content": "/**
 * React Hook for performance monitoring
 * Automatically starts monitoring in development environment
 * Outputs performance data to console
 */

import { useEffect, useRef } from 'react';
import { createFPSMonitor } from '../lib/performance/fpsMonitor';
import { createMemoryMonitor } from '../lib/performance/memoryMonitor';

export function usePerformanceMonitor(options = {}) {
  const fpsMonitorRef = useRef(null);
  const memoryMonitorRef = useRef(null);
  const intervalRef = useRef(null);

  const {
    enableFPS = true,
    enableMemory = true,
    fpsThreshold = 30,
    memoryWarningThreshold = 50 * 1024 * 1024,
    memoryCriticalThreshold = 100 * 1024 * 1024,
    logInterval = 10000, // Log every 10 seconds
    enabled = process.env.NODE_ENV === 'development'
  } = options;

  useEffect(() => {
    // Only run in development by default
    if (!enabled) {
      console.log('Performance monitoring disabled (production mode)');
      return;
    }

    console.log('Starting performance monitoring...');

    // Initialize FPS monitor
    if (enableFPS) {
      fpsMonitorRef.current = createFPSMonitor({
        threshold: fpsThreshold,
        warningCallback: (fps) => {
          console.warn(`[Performance] Low FPS: ${fps.toFixed(1)} FPS`);
        }
      });
      fpsMonitorRef.current.start();
    }

    // Initialize Memory monitor
    if (enableMemory) {
      memoryMonitorRef.current = createMemoryMonitor({
        warningThreshold: memoryWarningThreshold,
        criticalThreshold: memoryCriticalThreshold,
        warningCallback: (memoryInfo) => {
          const usedMB = (memoryInfo.usedJSHeapSize / (1024 * 1024)).toFixed(2);
          console.warn(`[Performance] Memory warning: ${usedMB}MB used`);
        },
        criticalCallback: (memoryInfo) => {
          const usedMB = (memoryInfo.usedJSHeapSize / (1024 * 1024)).toFixed(2);
          console.error(`[Performance] Critical memory: ${usedMB}MB used`);
        }
      });
    }

    // Periodic logging
    intervalRef.current = setInterval(() => {
      const logs = [];

      if (fpsMonitorRef.current) {
        const fps = fpsMonitorRef.current.getFPS();
        logs.push(`FPS: ${fps.toFixed(1)}`);
      }

      if (memoryMonitorRef.current) {
        const memoryInfo = memoryMonitorRef.current.getFormattedMemoryInfo();
        if (memoryInfo.message) {
          logs.push(memoryInfo.message);
        } else {
          logs.push(`Memory: ${memoryInfo.used} / ${memoryInfo.total} (${memoryInfo.usagePercent})`);
        }
      }

      if (logs.length > 0) {
        console.log(`[Performance] ${logs.join(' | ')}`);
      }
    }, logInterval);

    // Cleanup
    return () => {
      console.log('Stopping performance monitoring...');

      if (fpsMonitorRef.current) {
        fpsMonitorRef.current.stop();
      }

      if (memoryMonitorRef.current) {
        memoryMonitorRef.current.stopPeriodicCheck();
      }

      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
    };
  }, [enabled, enableFPS, enableMemory, fpsThreshold, memoryWarningThreshold, memoryCriticalThreshold, logInterval]);

  // Return current performance data
  const getPerformanceData = () => {
    return {
      fps: fpsMonitorRef.current?.getFPS() || 0,
      memory: memoryMonitorRef.current?.getFormattedMemoryInfo() || null
    };
  };

  return {
    getPerformanceData,
    fpsMonitor: fpsMonitorRef.current,
    memoryMonitor: memoryMonitorRef.current
  };
}

// Higher-order component for class components
export function withPerformanceMonitor(WrappedComponent, options = {}) {
  return function WithPerformanceMonitor(props) {
    usePerformanceMonitor(options);
    return <WrappedComponent {...props} />;
  };
}

export default usePerformanceMonitor;", "path": "/Users/charles/Desktop/folder/matrimonial/apps/web-admin/hooks/usePerformanceMonitor.js"}

