     2| * FPS Monitor
     3| * Uses requestAnimationFrame to calculate frames per second
     4| * Provides start/stop/getFPS API
     5| */
     6|
     7|class FPSMonitor {
     8|  constructor(options = {}) {
     9|    this.threshold = options.threshold || 30; // Default threshold: 30 FPS
    10|    this.warningCallback = options.warningCallback || this.defaultWarningCallback;
    11|    this.isRunning = false;
    12|    this.frameCount = 0;
    13|    this.lastTime = 0;
    14|    this.fps = 0;
    15|    this.animationFrameId = null;
    16|    this.boundLoop = this.loop.bind(this);
    17|  }
    18|
    19|  defaultWarningCallback(fps) {
    20|    console.warn(`Low FPS detected: ${fps.toFixed(1)} FPS (threshold: ${this.threshold})`);
    21|  }
    22|
    23|  loop(timestamp) {
    24|    if (!this.isRunning) return;
    25|
    26|    if (this.lastTime) {
    27|      const delta = timestamp - this.lastTime;
    28|      if (delta >= 1000) {
    29|        this.fps = (this.frameCount * 1000) / delta;
    30|        this.frameCount = 0;
    31|        this.lastTime = timestamp;
    32|        
    33|        if (this.fps < this.threshold) {
    34|          this.warningCallback(this.fps);
    35|        }
    36|      }
    37|    } else {
    38|      this.lastTime = timestamp;
    39|    }
    40|
    41|    this.frameCount++;
    42|    this.animationFrameId = requestAnimationFrame(this.boundLoop);
    43|  }
    44|
    45|  start() {
    46|    if (this.isRunning) return;
    47|    this.isRunning = true;
    48|    this.frameCount = 0;
    49|    this.lastTime = 0;
    50|    this.fps = 0;
    51|    this.animationFrameId = requestAnimationFrame(this.boundLoop);
    52|    console.log('FPS Monitor started');
    53|  }
    54|
    55|  stop() {
    56|    if (!this.isRunning) return;
    57|    this.isRunning = false;
    58|    if (this.animationFrameId) {
    59|      cancelAnimationFrame(this.animationFrameId);
    60|      this.animationFrameId = null;
    61|    }
    62|    console.log('FPS Monitor stopped');
    63|  }
    64|
    65|  getFPS() {
    66|    return this.fps;
    67|  }
    68|
    69|  isMonitoring() {
    70|    return this.isRunning;
    71|  }
    72|}
