     2| * Memory Monitor
     3| * Uses performance.memory API (Chrome) to monitor JS Heap usage
     4| * Provides getMemoryInfo API
     5| */
     6|
     7|class MemoryMonitor {
     8|  constructor(options = {}) {
     9|    this.warningThreshold = options.warningThreshold || 50 * 1024 * 1024; // 50MB default
    10|    this.criticalThreshold = options.criticalThreshold || 100 * 1024 * 1024; // 100MB default
    11|    this.warningCallback = options.warningCallback || this.defaultWarningCallback;
    12|    this.criticalCallback = options.criticalCallback || this.defaultCriticalCallback;
    13|    this.isSupported = this.checkSupport();
    14|    this.lastCheck = 0;
    15|    this.checkInterval = options.checkInterval || 5000; // Check every 5 seconds
    16|  }
    17|
    18|  checkSupport() {
    19|    return typeof performance !== 'undefined' && performance.memory !== undefined;
    20|  }
    21|
    22|  defaultWarningCallback(memoryInfo) {
    23|    const usedMB = (memoryInfo.usedJSHeapSize / (1024 * 1024)).toFixed(2);
    24|    const totalMB = (memoryInfo.totalJSHeapSize / (1024 * 1024)).toFixed(2);
    25|    console.warn(`Memory warning: ${usedMB}MB used of ${totalMB}MB total`);
    26|  }
    27|
    28|  defaultCriticalCallback(memoryInfo) {
    29|    const usedMB = (memoryInfo.usedJSHeapSize / (1024 * 1024)).toFixed(2);
    30|    const totalMB = (memoryInfo.totalJSHeapSize / (1024 * 1024)).toFixed(2);
    31|    console.error(`Critical memory usage: ${usedMB}MB used of ${totalMB}MB total`);
    32|  }
    33|
    34|  getMemoryInfo() {
    35|    if (!this.isSupported) {
    36|      return {
    37|        usedJSHeapSize: 0,
    38|        totalJSHeapSize: 0,
    39|        jsHeapSizeLimit: 0,
    40|        isSupported: false,
    41|        timestamp: Date.now()
    42|      };
    43|    }
    44|
    45|    const memory = performance.memory;
    46|    const memoryInfo = {
    47|      usedJSHeapSize: memory.usedJSHeapSize,
    48|      totalJSHeapSize: memory.totalJSHeapSize,
    49|      jsHeapSizeLimit: memory.jsHeapSizeLimit,
    50|      isSupported: true,
    51|      timestamp: Date.now()
    52|    };
    53|
    54|    // Check thresholds
    55|    if (memory.usedJSHeapSize > this.criticalThreshold) {
    56|      this.criticalCallback(memoryInfo);
    57|    } else if (memory.usedJSHeapSize > this.warningThreshold) {
    58|      this.warningCallback(memoryInfo);
    59|    }
    60|
    61|    return memoryInfo;
    62|  }
    63|
    64|  getMemoryUsagePercent() {
    65|    if (!this.isSupported) return 0;
    66|    const memory = performance.memory;
    67|    return (memory.usedJSHeapSize / memory.totalJSHeapSize) * 100;
    68|  }
    69|
    70|  getFormattedMemoryInfo() {
    71|    const info = this.getMemoryInfo();
    72|    if (!info.isSupported) {
    73|      return { message: 'Memory monitoring not supported in this browser' };
    74|    }
    75|
    76|    return {
    77|      used: `${(info.usedJSHeapSize / (1024 * 1024)).toFixed(2)} MB`,
    78|      total: `${(info.totalJSHeapSize / (1024 * 1024)).toFixed(2)} MB`,
    79|      limit: `${(info.jsHeapSizeLimit / (1024 * 1024)).toFixed(2)} MB`,
    80|      usagePercent: `${this.getMemoryUsagePercent().toFixed(2)}%`,
    81|      timestamp: new Date(info.timestamp).toISOString()
    82|    };
    83|  }
    84|
    85|  startPeriodicCheck() {
    86|    if (!this.isSupported) return;
    87|    
    88|    this.intervalId = setInterval(() => {
    89|      this.getMemoryInfo();
    90|    }, this.checkInterval);
    91|  }
    92|
    93|  stopPeriodicCheck() {
    94|    if (this.intervalId) {
    95|      clearInterval(this.intervalId);
    96|      this.intervalId = null;
    97|    }
    98|  }
    99|}
   100|
   101|// Singleton instance
   102|let instance = null;
   103|
   104|export function createMemoryMonitor(options) {
   105|  if (!instance) {
   106|    instance = new MemoryMonitor(options);
   107|  }
   108|  return instance;
   109|}
   110|
   111|export function getMemoryMonitor() {
   112|  return instance;
   113|}
   114|
