{"content": "     1|/**
     2| * React Hook for performance monitoring
     3| * Automatically starts monitoring in development environment
     4| * Outputs performance data to console
     5| */
     6|
     7|import { useEffect, useRef } from 'react';
     8|import { createFPSMonitor } from '../lib/performance/fpsMonitor';
     9|import { createMemoryMonitor } from '../lib/performance/memoryMonitor';
    10|
    11|export function usePerformanceMonitor(options = {}) {
    12|  const fpsMonitorRef = useRef(null);
    13|  const memoryMonitorRef = useRef(null);
    14|  const intervalRef = useRef(null);
    15|
    16|  const {
    17|    enableFPS = true,
    18|    enableMemory = true,
    19|    fpsThreshold = 30,
    20|    memoryWarningThreshold = 50 * 1024 * 1024,
    21|    memoryCriticalThreshold = 100 * 1024 * 1024,
    22|    logInterval = 10000, // Log every 10 seconds
    23|    enabled = process.env.NODE_ENV === 'development'
    24|  } = options;
    25|
    26|  useEffect(() => {
    27|    // Only run in development by default
    28|    if (!enabled) {
    29|      console.log('Performance monitoring disabled (production mode)');
    30|      return;
    31|    }
    32|
    33|    console.log('Starting performance monitoring...');
    34|
    35|    // Initialize FPS monitor
    36|    if (enableFPS) {
    37|      fpsMonitorRef.current = createFPSMonitor({
    38|        threshold: fpsThreshold,
    39|        warningCallback: (fps) => {
    40|          console.warn(`[Performance] Low FPS: ${fps.toFixed(1)} FPS`);
    41|        }
    42|      });
    43|      fpsMonitorRef.current.start();
    44|    }
    45|
    46|    // Initialize Memory monitor
    47|    if (enableMemory) {
    48|      memoryMonitorRef.current = createMemoryMonitor({
    49|        warningThreshold: memoryWarningThreshold,
    50|        criticalThreshold: memoryCriticalThreshold,
    51|        warningCallback: (memoryInfo) => {
    52|          const usedMB = (memoryInfo.usedJSHeapSize / (1024 * 1024)).toFixed(2);
    53|          console.warn(`[Performance] Memory warning: ${usedMB}MB used`);
    54|        },
    55|        criticalCallback: (memoryInfo) => {
    56|          const usedMB = (memoryInfo.usedJSHeapSize / (1024 * 1024)).toFixed(2);
    57|          console.error(`[Performance] Critical memory: ${usedMB}MB used`);
    58|        }
    59|      });
    60|    }
    61|
    62|    // Periodic logging
    63|    intervalRef.current = setInterval(() => {
    64|      const logs = [];
    65|      
    66|      if (fpsMonitorRef.current) {
    67|        const fps = fpsMonitorRef.current.getFPS();
    68|        logs.push(`FPS: ${fps.toFixed(1)}`);
    69|      }
    70|      
    71|      if (memoryMonitorRef.current) {
    72|        const memoryInfo = memoryMonitorRef.current.getFormattedMemoryInfo();
    73|        if (memoryInfo.message) {
    74|          logs.push(memoryInfo.message);
    75|        } else {
    76|          logs.push(`Memory: ${memoryInfo.used} / ${memoryInfo.total} (${memoryInfo.usagePercent})`);
    77|        }
    78|      }
    79|      
    80|      if (logs.length > 0) {
    81|        console.log(`[Performance] ${logs.join(' | ')}`);
    82|      }
    83|    }, logInterval);
    84|
    85|    // Cleanup
    86|    return () => {
    87|      console.log('Stopping performance monitoring...');
    88|      
    89|      if (fpsMonitorRef.current) {
    90|        fpsMonitorRef.current.stop();
    91|      }
    92|      
    93|      if (memoryMonitorRef.current) {
    94|        memoryMonitorRef.current.stopPeriodicCheck();
    95|      }
    96|      
    97|      if (intervalRef.current) {
    98|        clearInterval(intervalRef.current);
    99|      }
   100|    };
   101|  }, [enabled, enableFPS, enableMemory, fpsThreshold, memoryWarningThreshold, memoryCriticalThreshold, logInterval]);
   102|
   103|  // Return current performance data
   104|  const getPerformanceData = () => {
   105|    return {
   106|      fps: fpsMonitorRef.current?.getFPS() || 0,
   107|      memory: memoryMonitorRef.current?.getFormattedMemoryInfo() || null
   108|    };
   109|  };
   110|
   111|  return {
   112|    getPerformanceData,
   113|    fpsMonitor: fpsMonitorRef.current,
   114|    memoryMonitor: memoryMonitorRef.current
   115|  };
   116|}
   117|
   118|// Higher-order component for class components
   119|export function withPerformanceMonitor(WrappedComponent, options = {}) {
   120|  return function WithPerformanceMonitor(props) {
   121|    usePerformanceMonitor(options);
   122|    return <WrappedComponent {...props} />;
   123|  };
   124|}
   125|
   126|export default usePerformanceMonitor;", "total_lines": 125, "file_size": 3830, "truncated": false, "is_binary": false, "is_image": false}

